import { copyFile, mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { build } from "esbuild";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const root = path.resolve(__dirname, "../..");
const assetsRoot = path.join(root, "host-shell", "app", "assets");
const distRoot = path.join(assetsRoot, "dist");
const vendorRoot = path.resolve(root, "stock", "components", "vendor");
const manifestPath = path.join(__dirname, "bundle-manifest.json");
const rustOutPath = path.join(
  root,
  "server",
  "src",
  "http",
  "pages",
  "bundle_order_generated.rs",
);

function escapeRustStr(s) {
  return s.replace(/\\/g, "\\\\").replace(/"/g, '\\"');
}

function rustSliceConst(name, arr) {
  const body = arr.map((s) => `    "${escapeRustStr(s)}",`).join("\n");
  return `pub(super) const ${name}: &[&str] = &[\n${body}\n];`;
}

async function loadManifest() {
  const raw = await readFile(manifestPath, "utf8");
  const m = JSON.parse(raw);
  if (
    !Array.isArray(m.manageScripts) ||
    !Array.isArray(m.accessScripts) ||
    !Array.isArray(m.styles)
  ) {
    throw new Error(
      "bundle-manifest.json must contain manageScripts, accessScripts, styles arrays",
    );
  }
  if (!Array.isArray(m.configScripts)) {
    m.configScripts = [];
  }
  if (!Array.isArray(m.uploadScripts)) {
    m.uploadScripts = [];
  }
  if (!Array.isArray(m.adminScripts)) {
    m.adminScripts = [];
  }
  if (!Array.isArray(m.manageSourceScripts)) {
    m.manageSourceScripts = [];
  }
  return m;
}

async function writeRustBundleOrder(manifest) {
  const rust = `// AUTO-GENERATED by scripts/build/build-assets.mjs from scripts/build/bundle-manifest.json — DO NOT EDIT

${rustSliceConst("BUNDLE_MANAGE_SCRIPTS", manifest.manageScripts)}

${rustSliceConst("BUNDLE_MANAGE_SOURCE_SCRIPTS", manifest.manageSourceScripts)}

${rustSliceConst("BUNDLE_ACCESS_SCRIPTS", manifest.accessScripts)}

${rustSliceConst("BUNDLE_CONFIG_SCRIPTS", manifest.configScripts)}

${rustSliceConst("BUNDLE_UPLOAD_SCRIPTS", manifest.uploadScripts)}

${rustSliceConst("BUNDLE_ADMIN_SCRIPTS", manifest.adminScripts)}

${rustSliceConst("BUNDLE_STYLES_ORDER", manifest.styles)}
`;
  await writeFile(rustOutPath, rust, "utf8");
}

async function concatScripts(outputName, scripts) {
  let content = "// Generated by scripts/build/build-assets.mjs\n";
  for (const script of scripts) {
    const fullPath = path.join(assetsRoot, script);
    const scriptContent = await readFile(fullPath, "utf8");
    content += `\n/* ===== ${script} ===== */\n`;
    content += scriptContent;
    content += "\n";
  }
  const outputPath = path.join(distRoot, outputName);
  await writeFile(outputPath, content, "utf8");
  return outputPath;
}

async function bundleShoelace() {
  const outputPath = path.join(distRoot, "shoelace.bundle.js");
  // IIFE (not ESM): Tauri/WKWebView has repeatedly failed to upgrade <sl-*> when
  // shoelace is loaded as type=module from http://127.0.0.1 — undeclared
  // sl-dropdown then stretches the topbar and crushes the main pane.
  await build({
    entryPoints: [path.join(assetsRoot, "shoelace-local.js")],
    outfile: outputPath,
    bundle: true,
    minify: true,
    format: "iife",
    target: "es2020",
    legalComments: "none",
  });
  return outputPath;
}

async function bundleAuthRsa() {
  const outputPath = path.join(distRoot, "auth-rsa.bundle.js");
  await build({
    entryPoints: [path.join(assetsRoot, "auth", "rsa-oaep.js")],
    outfile: outputPath,
    bundle: true,
    minify: true,
    format: "iife",
    globalName: "MeiAuthRsa",
    target: "es2020",
    legalComments: "none",
  });
  return outputPath;
}

function stripJsSourceMapReference(js) {
  return String(js || "")
    .replace(/\/\/# sourceMappingURL=.*\r?\n?$/u, "")
    .replace(/\/\*# sourceMappingURL=.*?\*\/\s*$/u, "");
}

async function copyRuntimeVendorAssets() {
  const echartsSrc = path.join(root, "node_modules", "echarts", "dist", "echarts.min.js");
  const maplibreJsSrc = path.join(root, "node_modules", "maplibre-gl", "dist", "maplibre-gl.js");
  const maplibreCssSrc = path.join(root, "node_modules", "maplibre-gl", "dist", "maplibre-gl.css");
  const threeModuleSrc = path.join(root, "node_modules", "three", "build", "three.module.min.js");
  const threeCoreSrc = path.join(root, "node_modules", "three", "build", "three.core.min.js");
  const echartsDstDir = path.join(vendorRoot, "echarts");
  const maplibreDstDir = path.join(vendorRoot, "maplibre");
  const threeDstDir = path.join(vendorRoot, "three");
  await mkdir(echartsDstDir, { recursive: true });
  await mkdir(maplibreDstDir, { recursive: true });
  await mkdir(threeDstDir, { recursive: true });
  await copyFile(echartsSrc, path.join(echartsDstDir, "echarts.min.js"));
  const maplibreJs = stripJsSourceMapReference(await readFile(maplibreJsSrc, "utf8"));
  await writeFile(path.join(maplibreDstDir, "maplibre-gl.js"), maplibreJs, "utf8");
  await copyFile(maplibreCssSrc, path.join(maplibreDstDir, "maplibre-gl.css"));
  const threeModuleJs = stripJsSourceMapReference(await readFile(threeModuleSrc, "utf8"));
  await writeFile(path.join(threeDstDir, "three.module.min.js"), threeModuleJs, "utf8");
  const threeCoreJs = stripJsSourceMapReference(await readFile(threeCoreSrc, "utf8"));
  await writeFile(path.join(threeDstDir, "three.core.min.js"), threeCoreJs, "utf8");
  const orbitControlsSrc = path.join(root, "node_modules", "three", "examples", "jsm", "controls", "OrbitControls.js");
  let orbitControlsJs = stripJsSourceMapReference(await readFile(orbitControlsSrc, "utf8"));
  orbitControlsJs = orbitControlsJs.replace(/from 'three'/g, "from './three.module.min.js'");
  await writeFile(path.join(threeDstDir, "OrbitControls.js"), orbitControlsJs, "utf8");
  if (threeModuleJs.includes("three.core.min.js") && !threeCoreJs.trim()) {
    throw new Error("three vendor bundle incomplete: three.core.min.js is empty");
  }
}

async function concatStyles(outputName, styles) {
  let content = "/* Generated by scripts/build/build-assets.mjs */\n";
  for (const style of styles) {
    const fullPath = path.join(assetsRoot, style);
    const styleContent = await readFile(fullPath, "utf8");
    content += `\n/* ===== ${style} ===== */\n`;
    content += styleContent;
    content += "\n";
  }
  const outputPath = path.join(distRoot, outputName);
  await writeFile(outputPath, content, "utf8");
  return outputPath;
}

async function main() {
  const manifest = await loadManifest();
  await writeRustBundleOrder(manifest);
  await mkdir(distRoot, { recursive: true });
  await copyRuntimeVendorAssets();
  const manageOut = await concatScripts("manage.bundle.js", manifest.manageScripts);
  const manageSourceOut =
    manifest.manageSourceScripts.length > 0
      ? await concatScripts("manage-source.bundle.js", manifest.manageSourceScripts)
      : null;
  const accessOut = await concatScripts("access.bundle.js", manifest.accessScripts);
  const configOut =
    manifest.configScripts.length > 0
      ? await concatScripts("config.bundle.js", manifest.configScripts)
      : null;
  const uploadOut =
    manifest.uploadScripts.length > 0
      ? await concatScripts("upload.bundle.js", manifest.uploadScripts)
      : null;
  const adminOut =
    manifest.adminScripts.length > 0
      ? await concatScripts("admin.bundle.js", manifest.adminScripts)
      : null;
  const shoelaceOut = await bundleShoelace();
  const authRsaOut = await bundleAuthRsa();
  const stylesOut = await concatStyles("styles.bundle.css", manifest.styles);
  console.log("[assets:build] generated:");
  console.log(`- ${path.relative(root, rustOutPath)}`);
  console.log(`- ${path.relative(root, manageOut)}`);
  if (manageSourceOut) {
    console.log(`- ${path.relative(root, manageSourceOut)}`);
  }
  console.log(`- ${path.relative(root, accessOut)}`);
  if (configOut) {
    console.log(`- ${path.relative(root, configOut)}`);
  }
  if (uploadOut) {
    console.log(`- ${path.relative(root, uploadOut)}`);
  }
  if (adminOut) {
    console.log(`- ${path.relative(root, adminOut)}`);
  }
  console.log(`- ${path.relative(root, shoelaceOut)}`);
  console.log(`- ${path.relative(root, authRsaOut)}`);
  console.log(`- ${path.relative(root, stylesOut)}`);
  console.log(`- ${path.relative(root, path.join(vendorRoot, "echarts", "echarts.min.js"))}`);
  console.log(`- ${path.relative(root, path.join(vendorRoot, "maplibre", "maplibre-gl.js"))}`);
  console.log(`- ${path.relative(root, path.join(vendorRoot, "maplibre", "maplibre-gl.css"))}`);
  console.log(`- ${path.relative(root, path.join(vendorRoot, "three", "three.module.min.js"))}`);
  console.log(`- ${path.relative(root, path.join(vendorRoot, "three", "three.core.min.js"))}`);
  console.log(`- ${path.relative(root, path.join(vendorRoot, "three", "OrbitControls.js"))}`);
}

await main();
